export const js = "(function(){if(location.hash)return;try{history.scrollRestoration=\"manual\"}catch(e){}\nvar top=function(){window.scrollTo(0,0);try{document.documentElement.scrollIntoView({block:\"start\"})}catch(e){}};\ntop();document.addEventListener(\"DOMContentLoaded\",top);window.addEventListener(\"pageshow\",function(e){if(e.persisted)top()});\nwindow.addEventListener(\"load\",function(){if(window.scrollY<innerHeight)top()});})();\n;\n\n/* Always open a page at the top (hero), unless the link points to a section */\n(function(){try{if(\"scrollRestoration\" in history)history.scrollRestoration=\"manual\"}catch(e){}\n  function toTop(){var h=location.hash&&location.hash.length>1?document.getElementById(location.hash.slice(1)):null;\n    var html=document.documentElement,prev=html.style.scrollBehavior;html.style.scrollBehavior=\"auto\";\n    if(h){h.scrollIntoView()}else{window.scrollTo(0,0)}html.style.scrollBehavior=prev}\n  toTop();window.addEventListener(\"DOMContentLoaded\",toTop);window.addEventListener(\"load\",function(){toTop();setTimeout(toTop,60)});\n  window.addEventListener(\"pageshow\",function(e){if(e.persisted)toTop()});})();\n\n;\n/* Guires Insights: expert articles, guides, recognition and features from across the group. Newest first.\n   Fields: date, cat, biz, title, text, url (external), dateLabel (optional) */\nwindow.GUIRES_INSIGHTS = [\n  {date:\"2026-09-25\", cat:\"Expert guides\", biz:\"Guires Labs\", title:\"Functional beverages vs functional foods: the key rules\", text:\"Food Research Lab's regulatory team explains how claims, labelling and approvals differ between functional drinks and foods.\", url:\"https://www.foodresearchlab.com/\"},\n  {date:\"2026-09-16\", cat:\"Expert guides\", biz:\"Guires Labs\", title:\"EU novel food approval: a step-by-step pathway\", text:\"How new ingredients and foods are authorised under Regulation (EU) 2015/2283, from dossier to approval.\", url:\"https://www.foodresearchlab.com/\"},\n  {date:\"2026-09-11\", cat:\"Expert guides\", biz:\"Pubrica\", title:\"Responding to reviewer comments: a point-by-point rebuttal framework\", text:\"A practical Pubrica Academy guide to writing rebuttal letters that lead to successful manuscript revision.\", url:\"https://pubrica.com/academy/response-to-reviewer/responding-to-reviewer-comments-rebuttal-letter/\"},\n  {date:\"2026-09-10\", cat:\"Expert guides\", biz:\"Pubrica\", title:\"CONSORT 2025-compliant support for cardiovascular research\", text:\"What the updated CONSORT 2025 reporting standard means for cardiology trial manuscripts.\", url:\"https://pubrica.com/academy/journal-submission/cardiology-manuscripts-consort-2025-compliance/\"},\n  {date:\"2026-09-05\", cat:\"Expert guides\", biz:\"Pubrica\", title:\"Oncology manuscripts: CONSORT, RECIST and high-impact journal submission\", text:\"Reporting guidelines every oncology trial team should follow before submitting to a leading journal.\", url:\"https://pubrica.com/academy/journal-submission/oncology-manuscripts-consort-recist-submission/\"},\n  {date:\"2026-08-28\", cat:\"Expert guides\", biz:\"Guires Labs\", title:\"Cosmeceuticals in the UAE: cosmetic or drug?\", text:\"A claims guide for brands developing high-performance skincare for the Gulf market.\", url:\"https://www.foodresearchlab.com/\"},\n  {date:\"2025-03-22\", cat:\"Recognition\", biz:\"Guires Labs\", title:\"Guires Food Research Lab named among Top 10 Companies of 2025\", text:\"Industrial Magazine recognised Food Research Lab for leadership in R&D and pilot contract manufacturing.\", url:\"https://www.openpr.com/news/4085804/guires-food-research-lab-named-among-top-10-companies\"},\n  {date:\"2024-03-28\", cat:\"Media\", biz:\"Guires Labs\", title:\"Join the future of clean-label foods at Guires Food Research Lab\", text:\"Food Research Lab combines food science and culinary innovation to build products with clear, natural ingredient lists.\", url:\"https://www.openpr.com/news/3445390/join-the-future-of-clean-label-foods-at-guires-food-research-lab\"}\n];\n\n;\n\nconst REDUCE=matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\nconst $=id=>document.getElementById(id);\nconst CATSLUG={\"Corporate\":\"corporate\",\"Life at Guires\":\"life-at-guires\",\"Events\":\"events\",\"Thought leadership\":\"thought-leadership\",\"Recognition\":\"recognition\",\"Partnerships\":\"partnerships\",\"Media\":\"in-the-media\",\"Sustainability\":\"sustainability-initiatives\"};const HREF=n=>n.body?`/news/${CATSLUG[n.cat]}/${n.slug}`:n.url;\nconst NEWS=(window.GUIRES_INSIGHTS||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));\nconst CATC={\"Corporate\":\"--c-corp\",\"Expert guides\":\"--c-ins\",\"Life at Guires\":\"--c-life\",\"Recognition\":\"--c-rec\",\"Media\":\"--c-media\",\"Partnerships\":\"--c-part\",\"Events\":\"--c-evt\",\"Sustainability\":\"--c-sus\"};\nconst fmt=n=>n.dateLabel||new Date(n.date+\"T00:00:00\").toLocaleDateString(\"en-GB\",{day:\"numeric\",month:\"short\",year:\"numeric\"});\nconst today=new Date(\"2026-09-30T00:00:00\");\nconst isNew=n=>!n.dateLabel&&(today-new Date(n.date+\"T00:00:00\"))/864e5<=30;\nconst host=u=>{try{return new URL(u).hostname.replace(/^www\\./,\"\")}catch(_){return \"\"}};\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\n\n$(\"lastUpdate\").textContent=\"Latest update \u00b7 \"+fmt(NEWS[0]);\nconst tk=NEWS.slice(0,8).map(n=>`<a href=\"${HREF(n)}\"><time>${fmt(n)}</time>${esc(n.title)}</a>`).join(\"\");\n$(\"ticker\").innerHTML=tk+tk;\n\n/* filters */\nconst state={q:\"\",biz:\"\",cat:\"\"};\nconst bizs=[...new Set(NEWS.map(n=>n.biz))];\n$(\"biz\").innerHTML=`<option value=\"\">All businesses</option>`+bizs.map(b=>`<option>${esc(b)}</option>`).join(\"\");\n$(\"q\").addEventListener(\"input\",e=>{state.q=e.target.value.trim().toLowerCase();render()});\n$(\"biz\").addEventListener(\"change\",e=>{state.biz=e.target.value;render()});\n$(\"chips\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button\");if(b){state.cat=b.dataset.c;render()}});\n$(\"clear\").addEventListener(\"click\",()=>{state.q=\"\";state.biz=\"\";state.cat=\"\";$(\"q\").value=\"\";$(\"biz\").value=\"\";render()});\n\nfunction render(){\n  const cats=Object.keys(CATC).filter(c=>NEWS.some(n=>n.cat===c));\n  $(\"chips\").innerHTML=`<button type=\"button\" data-c=\"\" aria-pressed=\"${!state.cat}\" style=\"--c:var(--ink)\">All <span class=\"n\">${NEWS.length}</span></button>`+\n    cats.map(c=>`<button type=\"button\" data-c=\"${c}\" aria-pressed=\"${state.cat===c}\" style=\"--c:var(${CATC[c]})\">${c} <span class=\"n\">${NEWS.filter(n=>n.cat===c).length}</span></button>`).join(\"\");\n  const list=NEWS.filter(n=>(!state.cat||n.cat===state.cat)&&(!state.biz||n.biz===state.biz)&&(!state.q||(n.title+\" \"+n.text+\" \"+n.biz).toLowerCase().includes(state.q)));\n  $(\"count\").innerHTML=`<b>${list.length}</b> ${list.length===1?\"insight\":\"insights\"}`;\n  $(\"clear\").hidden=!(state.q||state.biz||state.cat);\n  if(!list.length){$(\"timeline\").innerHTML=`<p class=\"empty\">No insights match these filters.</p>`;return}\n  const years=[...new Set(list.map(n=>n.date.slice(0,4)))];\n  let k=0;\n  $(\"timeline\").innerHTML=years.map(y=>{const items=list.filter(n=>n.date.startsWith(y));\n    return `<div class=\"year\"><h3>${y}<small>${items.length} ${items.length===1?\"insight\":\"insights\"}</small></h3><div class=\"cards\">${items.map(n=>`\n      <a class=\"card\" href=\"${HREF(n)}\" style=\"--c:var(${CATC[n.cat]});--k:${Math.min(k++,10)*50}ms\">\n        <div class=\"meta\"><span class=\"cat\" style=\"--c:var(${CATC[n.cat]})\">${esc(n.cat)}</span><span>${fmt(n)}</span>${isNew(n)?'<span class=\"new\">New</span>':\"\"}</div>\n        <h4>${esc(n.title)}</h4><p>${esc(n.text)}</p>\n        <div class=\"foot\"><span class=\"src\">${esc(n.biz)}${n.body?\"\":\" \u00b7 \"+host(n.url)}</span><span>${n.body?\"Read story \u2192\":\"Read \u2197\"}</span></div>\n      </a>`).join(\"\")}</div></div>`}).join(\"\");\n}\nrender();\n\n$(\"menuBtn\").addEventListener(\"click\",()=>{const o=$(\"links\").classList.toggle(\"open\");$(\"menuBtn\").setAttribute(\"aria-expanded\",o)});\n\n/* headline words */\n(()=>{const h=$(\"heroTitle\");let i=0;const mk=()=>{const w=document.createElement(\"span\");w.className=\"w\";const s=document.createElement(\"span\");s.style.setProperty(\"--i\",i++);w.appendChild(s);return [w,s]};\n  [...h.childNodes].forEach(n=>{if(n.nodeType===3){const f=document.createDocumentFragment();n.textContent.split(/(\\s+)/).forEach(t=>{if(!t)return;if(/^\\s+$/.test(t)){f.appendChild(document.createTextNode(t));return}const [w,s]=mk();s.textContent=t;f.appendChild(w)});n.replaceWith(f)}else{const [w,s]=mk();n.replaceWith(w);s.appendChild(n)}})})();\n\n/* reveal + progress */\n(()=>{if(!REDUCE&&\"IntersectionObserver\" in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.remove(\"pre\");io.unobserve(e.target)}}),{threshold:.12});\n  document.querySelectorAll(\".rv\").forEach(e=>{if(e.getBoundingClientRect().top>innerHeight*.92){e.classList.add(\"pre\");io.observe(e)}})}\n  const bar=$(\"progress\");const upd=()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.style.transform=`scaleX(${m>0?scrollY/m:0})`};addEventListener(\"scroll\",upd,{passive:true});upd()})();\n\n/* hero: stars plus a broadcast signal wave */\n(()=>{const c=$(\"wave\"),x=c.getContext(\"2d\");let W,H,st=[],t=0;\n  function size(){const r=c.getBoundingClientRect(),d=devicePixelRatio||1;W=r.width;H=r.height;c.width=W*d;c.height=H*d;x.setTransform(d,0,0,d,0,0);\n    st=Array.from({length:Math.round(W*H/2600)},()=>({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.2+.2,p:Math.random()*6.3,s:.5+Math.random()*1.5,z:Math.random()}))}\n  function draw(){x.clearRect(0,0,W,H);if(!REDUCE)t+=.016;\n    for(const s of st){x.globalAlpha=(.35+.65*Math.abs(Math.sin(t*s.s+s.p)))*(.4+s.z*.6);x.fillStyle=\"#fff\";x.beginPath();x.arc(s.x,s.y,s.r,0,7);x.fill()}\n    const cx=W*.82,cy=H*.46;\n    for(let i=0;i<5;i++){const ph=((t*.35)+i/5)%1;x.globalAlpha=(1-ph)*.55;x.strokeStyle=\"#9FB4F0\";x.lineWidth=1.4;x.beginPath();x.arc(cx,cy,20+ph*Math.min(W,H)*.55,0,7);x.stroke()}\n    x.globalAlpha=1;x.fillStyle=\"#fff\";x.beginPath();x.arc(cx,cy,5,0,7);x.fill();\n    for(let l=0;l<3;l++){x.beginPath();x.globalAlpha=.35-l*.08;x.strokeStyle=[\"#9FB4F0\",\"#62C7CF\",\"#BD8BDB\"][l];x.lineWidth=1.6;\n      for(let px=0;px<=W;px+=6){const y=H*.82+Math.sin(px*.012+t*(1.2+l*.3)+l)*(14+l*6)*Math.sin(px/W*Math.PI);px?x.lineTo(px,y):x.moveTo(px,y)}x.stroke()}\n    x.globalAlpha=1;if(!REDUCE)requestAnimationFrame(draw)}\n  size();draw();addEventListener(\"resize\",()=>{size();if(REDUCE)draw()})})();\n\n\n;\n\n(()=>{const b=document.getElementById(\"menuBtn\"),l=document.getElementById(\"links\");if(!b||!l)return;\n  const sync=()=>{const o=l.classList.contains(\"open\");b.setAttribute(\"aria-expanded\",o);b.setAttribute(\"aria-label\",o?\"Close menu\":\"Open menu\")};\n  new MutationObserver(sync).observe(l,{attributes:true,attributeFilter:[\"class\"]});\n  document.addEventListener(\"keydown\",e=>{if(e.key===\"Escape\"&&l.classList.contains(\"open\")){l.classList.remove(\"open\");b.focus()}});\n  document.addEventListener(\"click\",e=>{if(l.classList.contains(\"open\")&&!l.contains(e.target)&&!b.contains(e.target))l.classList.remove(\"open\")});\n  l.addEventListener(\"click\",e=>{if(e.target.closest(\"a\"))l.classList.remove(\"open\")});})();\n";
